static bool  store_blob_data(lua_State *L, const char *table, const char *key, int value_len, const char *value)
{
    auto table_ptr = lua_touserdata(L, 1);
    if (table_ptr == nullptr)
    {
        return false;
    }

    auto slot = lua_getfield(L, 1, key);
    if (slot == LUA_TNONE)
    {
        return false;
    }

    if (lua_type(L, slot) != LUA_TSTRING)
    {
        return false;
    }

    size_t blob_size = strlen(value);
    if (blob_size > value_len)
    {
        return false;
    }

    memcpy(lua_tolstring(L, slot, &blob_size), value, blob_size);
    return true;
}

static bool  store_blob(lua_State *L, const char *table, const char *key, const char *value)
{
